insert into public.pay_rules (id, union_id, title, department_id, minimum_call_hours, overtime_after, overtime_multipliers, increment_minutes, meal_break_notes, notes, needs_verification, source_url, sort_order) values
  ('actra-ipa', 'u-actra', 'Independent Production Agreement (IPA) 2025–2027', null, null, array[8.00, 12.00]::numeric[], array[1.50, 2.00]::numeric[], 6, 'Meal breaks are unpaid. If production gives a 30-minute first meal instead, it is paid and counts as work time. Lunch is due within 6 hours (meal penalties after that).', 'The daily fee is the minimum for a day. Overtime is 150% of your contracted hourly rate after 8 hours worked and 200% after 12, in 6-minute units. The rate chart rounds overtime rates to the quarter (e.g. $182.50 for 150% of $121.25); CineArch calculates 150% exactly, so totals can differ by cents.', array['Background performer overtime thresholds: assumed to match principals (1.5x after 8 hours, 2x after 12)']::text[], 'https://actraottawa.ca/understanding-your-cheque-under-the-ipa/', 0),
  ('ubcp-bcmpa', 'u-ubcp', 'BC Master Production Agreement (BCMPA) 2025–2028', null, null, array[8.00, 12.00]::numeric[], array[1.50, 2.00]::numeric[], 6, 'Meal period due by the end of the 6th hour; meal penalties are paid at the overtime rate in 0.1-hour units until it starts.', 'The daily fee is the minimum for a day. 150% after 8 hours worked in a day, 200% after 12, in 0.1-hour units.', '{}'::text[], 'https://ubcpactra.ca/understanding-your-pay-cheque/', 10),
  ('iatse-873', 'u-873', 'IATSE 873 Long Term Agreement 2024–2028', null, 8.00, array[8.00, 12.00, 15.00]::numeric[], array[1.50, 2.00, 3.00]::numeric[], 6, 'Each meal period is 60 minutes and unpaid. If production calls a 30-minute catered first meal, it is paid work time. Under "Ontario Hours" the meal is paid.', 'Minimum call is 8 hours plus an unpaid meal. 1.5x after 8 hours up to the 12th, 2x from 12 to 15, 3x from the 16th hour, in 0.1-hour units. 6th and 7th days in a work week pay more (not yet calculated here).', '{}'::text[], 'https://amptp.org/wp-content/themes/amptp/assets/pdf/Canada/IATSE%20Local%20873/2024%20Local%20873%20Long%20Term%20Agreement.pdf', 20),
  ('iatse-873-transportation', 'u-873', 'IATSE 873 Long Term Agreement 2024–2028 — Transportation', 'transportation', 9.00, array[9.00, 12.00, 15.00]::numeric[], array[1.50, 2.00, 3.00]::numeric[], 6, 'Each meal period is 60 minutes and unpaid.', 'Transportation minimum call is 9 hours plus an unpaid meal. 1.5x after 9 hours up to the 12th, 2x from 12 to 15, 3x from the 16th hour.', '{}'::text[], 'https://amptp.org/wp-content/themes/amptp/assets/pdf/Canada/IATSE%20Local%20873/2024%20Local%20873%20Long%20Term%20Agreement.pdf', 30);
